function HatBandBuckleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HatBandBuckleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HatBandBuckleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HatBandBuckleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HatBandBuckleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatBandBuckleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatBandBuckleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatBandBuckleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatBandBuckleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatBandBuckleMaker.buildings==0 then return false,"Potrebna sponcna delavnica" end; if not HatBandBuckleMaker.maker then return false,"Potreben sponkar" end; return true end
function HatBandBuckleMaker.make(pt,qty) qty=qty or 1; local ok,e=HatBandBuckleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HatBandBuckleMaker.ironStock=HatBandBuckleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HatBandBuckleMaker.bronzeStock=HatBandBuckleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HatBandBuckleMaker.woodStock=HatBandBuckleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HatBandBuckleMaker.leatherStock=HatBandBuckleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatBandBuckleMaker.silverStock=HatBandBuckleMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatBandBuckleMaker.goldStock=HatBandBuckleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatBandBuckleMaker.jewelStock=HatBandBuckleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatBandBuckleMaker.pearlStock=HatBandBuckleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatBandBuckleMaker.maker then t=math.max(1,t-math.floor(HatBandBuckleMaker.maker.skill/13)) end; table.insert(HatBandBuckleMaker.activeMaking,{id="hatbandbuckle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
