function HatBandBuckleMaker.update(dt) if not _G.state then return end; HatBandBuckleMaker.dayTimer=HatBandBuckleMaker.dayTimer+dt; if HatBandBuckleMaker.dayTimer>=30 then HatBandBuckleMaker.dayTimer=0; for i=#HatBandBuckleMaker.activeMaking,1,-1 do local m=HatBandBuckleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatBandBuckleMaker.completeMaking(m); table.remove(HatBandBuckleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatBandBuckleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatBandBuckleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
